from taf.internal.bmc import BmcClient


class BmcConnection(object):
    """
    Usage example:
        >>> bmc_conn = BmcConnection(address="127.0.0.1", port=443, username="admin", password="password")
        >>> result = bmc_conn.computer_system_on()


        To check if communication was successful:
            >>> result.status
            >>> 200


        To check if action was successful:
            >>> result.dict
            >>> {'System reset result': 'Success.'}
    """

    def __init__(self, address, username, password, port=443, interface='redfish_rm_17'):
        """
        Connects to desired BMC interface.

        :param str address: BMC interface ip address ie. 127.0.0.1
        :param int port: Port number, Default is 443
        :param str username: BMC endpoint username
        :param str password: BMC endpoint password for username
        :param str interface: (Optional) Version of BMC interface (default is AirFrame Redfish RM17)
                              Supported versions: 'redfish_rm_17', 'redfish_oe_19', 'redfish_oe_20', 'redfish_oe_22'
        :raises: Exceptions are documented in taf.internal.bmc supported interfaces
        """

        self.__interface = BmcClient.create_connection(
            address=address,
            port=port,
            interface=interface,
            interface_parameters={
                "username": username,
                "password": password
            }
        )

    def computer_system_reset_forceoff(self):
        """
        Method performs "poweroff" on the Connection object instance of endpoint system.

        Usage:
            >>> result = obj.computer_system_reset_forceoff(connection_object)
            >>> result.status
            >>> 200
            >>> result.dict
            >>> {'System reset result': 'Success.'}

        :return: taf.internal.bmc.interfaces.bmc.BmcResponse with function result.
        :raises: Exceptions are documented in taf.internal.bmc supported interfaces
        """
        return self.__interface.system.power_off_immediate()

    def computer_system_on(self):
        """
        Method performs "power on" on the Connection object instance of endpoint system.

        Usage:
            >>> result = obj.computer_system_on(connection_object)
            >>> result.status
            >>> 200
            >>> result.dict
            >>> {'System reset result': 'Success.'}

        :return: taf.internal.bmc.interfaces.bmc.BmcResponse with function result.
        :raises: Exceptions are documented in taf.internal.bmc supported interfaces
        """
        return self.__interface.system.power_on()

    def disconnect(self):
        """
        Disconnect given BMC Connection from endpoint.

        :return: Nothing
        :raises: Exceptions are documented in taf.internal.bmc supported interfaces
        """
        self.__interface.logout()
